import json, sys
data = json.load(sys.stdin)
# Compare with baseline
with open('baseline-packages.json') as f:
    baseline = json.load(f)

# Build lookup: project -> framework -> package -> version
def build_lookup(d):
    result = {}
    for proj in d['projects']:
        pname = proj['path'].split('/')[-2]
        result[pname] = {}
        for fw in proj['frameworks']:
            result[pname][fw['framework']] = {p['id']: p['resolvedVersion'] for p in fw['topLevelPackages']}
    return result

b = build_lookup(baseline)
a = build_lookup(data)

changes = []
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    for fw in sorted(set(list(b.get(proj,{}).keys()) + list(a.get(proj,{}).keys()))):
        bp = b.get(proj,{}).get(fw,{})
        ap = a.get(proj,{}).get(fw,{})
        for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
            bv = bp.get(pkg, 'N/A')
            av = ap.get(pkg, 'N/A')
            if bv != av:
                changes.append(f'{proj}/{fw}: {pkg} {bv} -> {av}')

if changes:
    print('VERSION CHANGES:')
    for c in changes:
        print(f'  {c}')
else:
    print('NO VERSION CHANGES - conversion is version-neutral')
"

